package com.yuegang.zhihui.admin.api;import com.yuegang.zhihui.admin.application.*;import com.yuegang.zhihui.admin.security.*;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.common.web.*;import jakarta.servlet.http.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/admin")public final class AdminController{private final AdminDashboardService service;private final AdminUserVerifier users;public AdminController(AdminDashboardService s,AdminUserVerifier u){service=s;users=u;}@GetMapping("/dashboard")ApiResponse<AdminDashboardView>dashboard(HttpServletRequest r){users.verify(r);return ApiResponse.success(service.dashboard(),TraceIdResolver.resolve(r));}}
